import csv, json
from datetime import datetime, timedelta

def parse(ts):
    return datetime.strptime(ts, '%Y-%m-%d %H:%M')

rows = []
with open('data/sensor_log.csv') as f:
    r = csv.DictReader(f)
    for row in r:
        ts = row['timestamp']
        # day shift 2026-09-10 06:00 inclusive .. 14:00 exclusive (per shifts.csv)
        if '2026-09-10 06:00' <= ts < '2026-09-10 14:00':
            rows.append(row)

machines = {}
for row in rows:
    machines.setdefault(row['machine_id'], []).append((parse(row['timestamp']), row['state']))

def gaps(m, events):
    gs = []
    for a,b in zip(events, events[1:]):
        if (b[0]-a[0]).total_seconds() != 60:
            gs.append((a[0], b[0], (b[0]-a[0]).total_seconds()/60))
    return gs

